%[text] # Spike Exploration
%[text] spikeArtifacts.mlx illustrates specific issues in the analysis of extracellular recordings. This script builds on that to explore some additional parameter dependencies.
%[text:tableOfContents]{"heading":"Table of Contents"}
%[text] 
%[text] %[text:anchor:H_9BC26763] ## Setup Simulation
%[text] Simulation parameters
run('../startup'); % Make sure all toolboxes are on the path
clear spkDefaults arDefaults % Avoid lingering values from prevoous runs
spkDefaults.duration                  = 120;    % 2 min
spkDefaults.stimulatorSamplingRate    = 1e3;     % e.g., Starstim (1 kHz)
spkDefaults.currentResolution         = 1e-6;    % 1 muA
spkDefaults.resistance                = 1;        % 1 mA -> 1 mV artifact
spkDefaults.recordingSamplingRate     = 30e3;     % 30kHz
spkDefaults.adcLinearRange            = 6.8e-3;   % Linear range of amplified 6.8 mV
spkDefaults.adcNonlinearity           = 100;      % Piecewise linear
spkDefaults.adcRange                  = 10e-3;     % Input range of the ADC.
spkDefaults.adcBitDepth               = 16;       % Number of bits in the AD convertor
spkDefaults.adcGain                   = 20;       % Amplify 20x
spkDefaults.highPass                  = 0.01;     % High pass filter on the preamp. 
spkDefaults.reproducible              = 2;       % Seed the RNG to get reproducible results
%[text] Define the common neural signals
spkDefaults.spikePeak                 = 60e-6;   % 60 muV
spkDefaults.spikeRate                 = 100;      % 100 spk/s
spkDefaults.poisson                           = true;     % Poisson spiking
spkDefaults.fixNrSpikes               = true;     % Deviate from Poisson to get exact firing rate.
spkDefaults.refractoryPeriod          = 1.5e-3;   % 1.5 ms
spkDefaults.additive                  = 20e-6;    % Background activity/noise
spkDefaults.pinkNoise                 = true;     % Pink background noise
spkDefaults.synchrony                 = 0;        % Poisson random spikes, no relation with LFP
spkDefaults.lfpAmplitude              = 0;        % No intrinsic oscillation
spkDefaults.multiplicative            = 0;        % No multiplicative noise

%[text] Define the common parameters for artifact removal
arDefaults.slide                     = false;   % No sliding segment
arDefaults.slack                     = 5e-3;    % 5 ms to realign segments
arDefaults.nrSegsPerWindow           = 10;      % 10 segments to average artifact
arDefaults.pcaNr                     = 2;       % First two PC are removed
arDefaults.pcaVarExplained           = Inf;     % Ignore explained variance, always remove 2.
arDefaults.pcaNrSegsPerWindow        = Inf;     % Use all segments (plus the tACS signal; below) to determine basis set.
arDefaults.referenceSegment          = 1;       % Align to first segment
arDefaults.recordingSamplingRate      = spkDefaults.recordingSamplingRate; % Match to the recording
%[text] Define the filter that extract signals in the "spike band":
lowCut                      = 500;  % high pass filter cut off
highCut                     = 7000; % Low pass filter cut off.
filterOrder                 = 3; % Filter order  (Butterworth)
%%
%[text] %[text:anchor:H_D38DE7B6] ## Frequency dependence
%[text] The spectral analysis (spikeArtifacts.mlx) shows that the contamination of the spike band depends on the frequency of tACS. Here I investigate how how different tACS frequencies affect the fraction of false negatives (for the current choices of neural signal, noise, and thresholds, the false positive rate is negligible).
methods  =["NOP" "FASTR" "RBAR"];
spk = artSim(spkDefaults);
ar = arDefaults;
spk.tacsAmplitude             = 120e-6;   % A->V artifact
nrMethods = numel(methods);
falsePositive = nan(2,nrTacsFreqs,nrMethods);
falseNegative = nan(2,nrTacsFreqs,nrMethods);
oldState =[];
for m=1:nrMethods %[output:group:53c10f49]
    for i=1:nrTacsFreqs
        spk.tacsFrequency = tacsFreqs(i);
        [~,falsePositive(:,i,m),falseNegative(:,i,m)] = simPlotSpikes(spk,ar,methods(m),lowCut=lowCut,highCut=highCut,filterOrder=filterOrder,threshold=threshold,spikeSortingMode=spikeSortingMode,axs=gobjects(4));         %[output:65193789] %[output:0dda6550] %[output:1e8edf0a] %[output:4ab14349] %[output:6799ee45] %[output:577275d1] %[output:4185e153] %[output:11c5ed73] %[output:9907f0d5] %[output:0d4ed2cf] %[output:0ac340a3]
    end
end %[output:group:53c10f49]

%%
%[text] Generate a figure illustrating the stimuation frequency dependence.
[f,ax] = fig('Name','frequency','paperCols',2,'height',4,'nrRows',1,'nrCols',3); %[output:3121117f]
for method =1:nrMethods
    axes(ax(method)) %[output:3121117f]
    hold on
    plot(tacsFreqs,falseNegative(:,:,method)','LineStyle','-');
    xlabel 'tACS frequency (Hz)'
    ylabel 'False Negatives (%)'
    set(gca,'XTick',tacsFreqs);
    title (methods(method))
    
end
legend ('Sham','tACS','Location','south') %[output:3121117f]

%%
%[text] ## Interactions
%[text] %[text:anchor:TMP_4a45] The simulations above show a non zero false negative rate after FASTR and that the tACS signal affects the results in the non-tACS trials (due to the shared voltage threshold and waveform clustering procedure). The percentages shown depend on the randomization; to quantify an average effect, I bootstrapped this.
spk = artSim(spkDefaults);
ar = arDefaults;
spk.tacsAmplitude    = 120e-6;   % A->V artifact
spk.tacsFrequency    = 40; % Example frequency
spk.reproducible     = false; % Do not reset the RNG
nrBootstraps = 100;
falseNegFastr= nan(2,nrBootstraps);
% Use a parfor as this takes a while
parfor i=1:nrBootstraps         %[output:group:7d418ae6] %[output:69472c8b]
    [~,~,falseNegFastr(:,i)] = simPlotSpikes(spk,ar,"FASTR",lowCut=lowCut,highCut=highCut,filterOrder=filterOrder,threshold=threshold,spikeSortingMode=spikeSortingMode,axs=gobjects(4));        
end %[output:group:7d418ae6]
%%
%[text] FIgure to show the results.
[~,axs] = fig('Name','Interactions','nrRows',1,'nrCols',2); %[output:344fede1]
axes(axs(1)) %[output:344fede1]
mFalseNegFastr = mean(falseNegFastr,2,"omitmissing");
sdFalseNegFastr = std(falseNegFastr,0,2,"omitmissing");
bar(mFalseNegFastr); %[output:344fede1]
hold on %[output:344fede1]
errorbar(mFalseNegFastr,sdFalseNegFastr,'.') %[output:344fede1]
set(gca,'XTick',1:2,'XTickLabel',{'Sham','tACS'}); %[output:344fede1]
ylabel ('False Negatives (%)'); %[output:344fede1]
axes(axs(2)) %[output:344fede1]
plot(falseNegFastr(2,:),falseNegFastr(1,:),'.') %[output:344fede1]
xlabel 'tACS' %[output:344fede1]
ylabel 'Sham' %[output:344fede1]
r= corrcoef(falseNegFastr');
title (sprintf('Cross Contamination: r = %.2f',r(1,2))); %[output:344fede1]

%%
%[text] ## tDCS
%[text] Repeat with tDCS and a heartbeat artifact.
spk = artSim(spkDefaults);
ar = arDefaults;
spk.tacsAmplitude    = 0;    % A->V artifact
spk.tdcsMean         = 1e-3;   % A->V artifact

spk.zFun                      = @zHeartbeat;
spk.zAmplitude                = 0.05;
spikeSortingMode                ="ALL";

[~,axs] = fig('Name',"tDCS",'paperCols',2,'height',12,'nrRows',2,'nrCols',2,'byColumn',false);    %[output:78badf4b]
[sortResultsNopAll]  = simPlotSpikes(spk,ar,"NOP",xlim = 8+[0 0.1],lowCut=lowCut,highCut=highCut,filterOrder=filterOrder,threshold=threshold,sharedThreshold = sharedThreshold, spikeSortingMode=spikeSortingMode,axs=[axs(1:2)' gobjects(2)]); %[output:85c803b9] %[output:78badf4b]
spikeSortingMode                ="MATCHSHAM";
[sortResultsNop]  = simPlotSpikes(spk,ar,"NOP",phaseFromRaw = true,lowCut=lowCut,highCut=highCut,filterOrder=filterOrder,threshold=threshold,sharedThreshold = sharedThreshold, spikeSortingMode=spikeSortingMode,axs=[gobjects(1,2) axs(3:4)]); %[output:4ba1c49b] %[output:78badf4b]
%[text] The heartbeat artifact does not seem to affect the spike results. Not too surprising given that cardioballistic (and most other physiological artifacts) are low frequency events, far outside the spike band. 
%[text] 
%[text] 

